from jsonb_to_recordset($json$[{"id":"che-so-176","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A non-ideal solution is one that","options":["deviates from Raoult’s law","obeys Raoult’s law at every mole fraction","has $\\Delta H_{\\mathrm{mix}}$ exactly zero","never boils"],"answer_index":0,"explanation":"Any measurable departure of vapour pressure from $p_i^\\circ x_i$ marks non-ideality.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-177","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Positive deviation from Raoult’s law means the observed vapour pressure is","options":["higher than the ideal value","lower than the ideal value","exactly zero","equal to $K_H$"],"answer_index":0,"explanation":"Weaker A–B forces let molecules escape more easily, so $p > p_{\\mathrm{ideal}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-178","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Negative deviation from Raoult’s law is accompanied by","options":["$\\Delta H_{\\mathrm{mix}} < 0$","$\\Delta H_{\\mathrm{mix}} > 0$","$\\Delta H_{\\mathrm{mix}} = 0$","$\\Delta V_{\\mathrm{mix}} > 0$ in every case"],"answer_index":0,"explanation":"Stronger A–B attractions release heat on mixing (exothermic).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-179","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For a positively deviating pair, mixing typically causes the volume to","options":["increase ($\\Delta V_{\\mathrm{mix}} > 0$)","decrease","stay exactly additive","collapse to zero"],"answer_index":0,"explanation":"Weaker unlike attractions leave a slightly expanded, less tightly packed liquid.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-180","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Chloroform and acetone show negative deviation because","options":["a hydrogen-bond-like attraction forms between the two molecules","the liquids repel strongly","they are immiscible","they ionise completely"],"answer_index":0,"explanation":"The chloroform hydrogen interacts with the acetone oxygen, strengthening A–B forces.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-181","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Ethanol–acetone is a common Intermediate example of","options":["positive deviation","negative deviation","an ideal mix","a solid solution"],"answer_index":0,"explanation":"Mixing breaks some ethanol hydrogen bonds, so A–B is weaker than A–A and the pair shows positive deviation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-182","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"n-Hexane and n-heptane are expected to behave as","options":["an ideal solution","a strongly positive pair","a strongly negative pair","an azeotrope only"],"answer_index":0,"explanation":"Adjacent homologues have nearly identical London forces, so the mix is essentially ideal.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-183","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"When A–B attractions are weaker than A–A and B–B, the mixture shows","options":["positive deviation and often a minimum-boiling azeotrope","negative deviation and a maximum-boiling azeotrope","strictly ideal behaviour","zero vapour pressure"],"answer_index":0,"explanation":"Weaker unlike forces raise vapour pressure; a maximum in p versus x gives a minimum-boiling azeotrope.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-184","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Nitric acid and water mix with heat released and a vapour-pressure curve below the Raoult line. The deviation is","options":["negative","positive","ideal","undefined"],"answer_index":0,"explanation":"Exothermic mixing plus $p < p_{\\mathrm{ideal}}$ is the signature of negative deviation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-185","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Carbon disulphide and acetone form a pair with weaker unlike interactions, so one expects","options":["positive deviation","negative deviation","$\\Delta H_{\\mathrm{mix}} = 0$","i = 2"],"answer_index":0,"explanation":"CS2–acetone is a standard positively deviating pair.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
